/**
 * A radar chart profiling items over shared-unit axes (`design/components/radar-chart.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/radar-chart.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  DEFAULT_CHART_MESSAGES,
  Each,
  Icon,
  UNMEASURED,
  agentMember,
  chartHiddenSeries,
  chartMarks,
  chartPosition,
  chartSeries,
  chooseChartMark,
  claimSlot,
  createCell,
  createDerived,
  createReading,
  createWarningLog,
  devWarning,
  elementRef,
  measureBox,
  nearest2D,
  radarChartModel,
  radarChartReadout,
  radarChartSelection,
  readChartCap,
  readChartPosition,
  readingRest,
  readingView,
  scope,
  toggleChartSeries,
  toggleSeries,
  watchEffect,
  type ChartMessages,
  type ChartSeries,
  type ChartTooltipConfig,
  type Defaults,
  type RadarAxis,
  type ValueFormat,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/charts/radar-chart.module.css'
import a11y from '@polymorph/recipes/conventions/a11y.module.css'
import chartFrame from '@polymorph/recipes/charts/frame/chart-frame.module.css'
import chartLegend from '@polymorph/recipes/charts/frame/chart-legend.module.css'
import chartTooltip from '@polymorph/recipes/charts/frame/chart-tooltip.module.css'
import chartTwin from '@polymorph/recipes/charts/frame/chart-twin.module.css'
import Button from '../controls/Button'
import Table from '../structure/Table'
import TableBody from '../structure/TableBody'
import TableCell from '../structure/TableCell'
import TableHead from '../structure/TableHead'
import TableHeader from '../structure/TableHeader'
import TableRow from '../structure/TableRow'

export interface RadarChartProps {
  /**
   * The spokes, **3–6**, drawn clockwise from 12 o'clock in the given order. Fewer than 3 raises
   * a dev warning, because two values read better side by side; more than 6 raises one, because
   * the polygon becomes unreadable. The chart still draws every axis it is given, because a
   * warning never hides data.
   */
  axes: readonly RadarAxis[]
  /**
   * **One row per axis, in the axes' order**; row *i* binds to `axes[i]`. A count mismatch
   * raises a dev warning naming both lengths. Each row has one field per series key, and `null`
   * is a **gap**: the polygon breaks at that vertex instead of dipping to zero.
   */
  data: readonly Readonly<Record<string, string | number | null>>[]
  /**
   * Formats values in the tooltip and twin. There is no `y` prop: the one shared scale runs from
   * zero to the nice'd maximum across **all** series and axes, and nothing is configurable per
   * axis.
   */
  format?: ValueFormat
  /**
   * The accessible name.
   */
  label: string
  /**
   * Shows the previous frame at reduced opacity during a refetch.
   */
  loading?: boolean
  /**
   * The locale for `Intl` formatting.
   */
  locale?: string
  /**
   * The chart tier's string catalog (`ChartMessages`). Defaults to generic English; a localized
   * host passes the same object to every chart.
   */
  messages?: ChartMessages
  /**
   * Called with the axis key, series key and value at the reading position, on Enter, Space or
   * click.
   */
  onSelect?: (selection: { axis: string; key: string; value: number }) => void
  /**
   * The polygons, **at most the palette's cap**. Polygons can cross anywhere, so
   * `--pm-chart-cap` limits them as it limits Scatter.
   */
  series: readonly ChartSeries[]
  /**
   * The chart size; the outer radius fits the plot's shorter side, as in DonutChart.
   */
  size?: 'sm' | 'md' | 'lg'
  /**
   * The per-vertex readout: an axis label header (`hideLabel` removes it), then the series key
   * glyph, series label and formatted value.
   */
  tooltip?: false | ChartTooltipConfig
}

/** A radar chart profiling items over shared-unit axes. */
export default function RadarChart(given: RadarChartProps): JSX.Element {
  const props = mergeProps(
    {
      size: 'md',
      tooltip: (() => ({}))(),
      loading: false,
      messages: (() => DEFAULT_CHART_MESSAGES)(),
    } as Defaults<RadarChartProps, 'size' | 'tooltip' | 'loading' | 'messages'>,
    claimSlot(given),
  )
  return scope(() => {
    const box = createCell(UNMEASURED)
    const reading = createCell(createReading({ count: 0, seriesStart: 0 }))
    const position = createCell(readingRest(0))
    const hidden = createCell(new Set<string>())
    const twinOpen = createCell(false)
    const warningLog = createCell(createWarningLog())
    const cap = createCell(readChartCap(null))
    const frame = elementRef<HTMLElement>()
    const plot = elementRef<HTMLElement>()
    const input = createDerived(() => ({
      axes: props.axes,
      data: props.data,
      series: props.series,
      format: props.format,
      label: props.label,
      locale: props.locale,
      messages: props.messages,
      tooltip: props.tooltip,
      loading: props.loading,
      selectable: props.onSelect !== undefined,
      hidden: hidden.value,
      cap: cap.value,
      box: box.value,
    }))
    const model = createDerived(() => radarChartModel(input.value))
    const view = createDerived(() =>
      readingView(position.value, props.axes.length, model.value.visible.length),
    )
    const readout = createDerived(() => radarChartReadout(input.value, model.value, view.value))
    const walked = createDerived(() => view.value.series ?? 0)
    const activate = createDerived(() => () => {
      const selection = radarChartSelection(input.value, model.value, reading.value.now())
      if (selection !== null) props.onSelect?.(selection)
    })
    const walk = createDerived(() => ({
      count: props.axes.length,
      seriesCount: model.value.visible.length,
      walkSeries: true,
      seriesStart: 0,
      wrap: true,
    }))
    const marks = createDerived(() => ({
      walk: walk.value,
      input: input.value,
      model: model.value,
      readout: radarChartReadout,
      selection: radarChartSelection,
    }))
    const onKey = createDerived(() => (event: KeyboardEvent) => {
      if (props.onSelect !== undefined && (event.key === 'Enter' || event.key === ' ')) {
        event.preventDefault()
        activate.value()
        return
      }
      reading.value.update(walk.value)
      if (reading.value.key(event.key)) event.preventDefault()
    })
    const onPointer = createDerived(() => (event: PointerEvent) => {
      if (model.value.plot === null) return
      const rect = (event.currentTarget as Element).getBoundingClientRect()
      const hit = nearest2D(
        model.value.positions,
        event.clientX - rect.left,
        event.clientY - rect.top,
      )
      if (hit === -1) {
        reading.value.clear()
        return
      }
      reading.value.moveTo(hit % props.axes.length, Math.floor(hit / props.axes.length))
    })
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const run = () => {
        box.value = plot.value === null ? box.value : measureBox(plot.value, box.value)
      }
      const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
      for (const element of [plot.value]) if (element) resize?.observe(element)
      release1 = () => {
        resize?.disconnect()
      }
      run()
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    const effect2 = () => {
      reading.value.subscribe((now) => {
        position.value = now
      })
    }
    onMount(effect2)
    const effect3 = () => {
      warningLog.value.log(model.value.warnings, (message) => devWarning(true, message))
    }
    watchEffect(
      createMemo(() => model.value.warnings.join('\n')),
      effect3,
      true,
    )
    const effect4 = () => {
      cap.value = model.value.state === 'empty' ? cap.value : readChartCap(plot.value)
    }
    watchEffect(
      createMemo(() => model.value.state === 'empty'),
      effect4,
      true,
    )
    let release5: (() => void) | undefined
    const effect5 = () => {
      release5?.()
      const ran =
        !(props.onSelect !== undefined) && !model.value.legend
          ? () => {}
          : agentMember({
              member: 'RadarChart',
              element: () => frame.value,
              state: () => ({
                items: props.onSelect !== undefined ? chartMarks(marks.value, reading.value) : [],
                position: chartPosition(marks.value, reading.value),
                count: walk.value.count,
                series: chartSeries(frame.value, chartLegend.key, model.value.painted),
                hidden: chartHiddenSeries(frame.value, chartLegend.key, model.value.painted),
              }),
              actions: {
                read: {
                  argument: 'number',
                  run: (value) => readChartPosition(marks.value, value, reading.value),
                },
                choose: {
                  argument: 'id',
                  among: 'items',
                  run: (value) =>
                    chooseChartMark(marks.value, value, reading.value, activate.value),
                },
                toggle: {
                  argument: 'id',
                  among: 'series',
                  run: (value) =>
                    toggleChartSeries(frame.value, chartLegend.key, model.value.painted, value),
                },
              },
            })
      release5 = () => {
        ran()
      }
    }
    onMount(effect5)
    onCleanup(() => release5?.())
    return (
      <figure
        class={chartFrame.frame}
        data-size={props.size}
        data-state={model.value.state}
        data-position={view.value.active ? view.value.index : undefined}
        aria-label={props.label}
        data-member="radar-chart"
        ref={frame.attach}
      >
        {/* region */}
        <div class={chartFrame.region}>
          {/* y axis */}
          <div class={chartFrame.yAxis} />
          {/* plot */}
          <div class={chartFrame.plot} ref={plot.attach}>
            {model.value.state === 'empty' ? (
              <div class={chartFrame.empty}>
                <span>{props.messages.empty}</span>
              </div>
            ) : (
              <div
                class={styles.surface}
                tabindex="0"
                role="img"
                aria-label={props.label}
                onkeydown={($event: KeyboardEvent) => onKey.value($event)}
                onclick={() => activate.value()}
                onpointermove={($event: PointerEvent) => onPointer.value($event)}
                onpointerleave={() => reading.value.clear()}
                onblur={() => reading.value.clear()}
              >
                {model.value.plot !== null ? (
                  <svg
                    class={styles.marks}
                    data-reading={view.value.active ? '' : undefined}
                    width={model.value.plot?.width}
                    height={model.value.plot?.height}
                    aria-hidden="true"
                    {...{ focusable: 'false' }}
                  >
                    {/* centre */}
                    <g transform={model.value.plot?.transform}>
                      {/* grid */}
                      <g class={styles.grid}>
                        <Each of={model.value.plot?.grid ?? []} by={(line) => line.key} renew>
                          {(line) => <path d={line.d} />}
                        </Each>
                      </g>
                      {/* profiles */}
                      <g class={styles.profiles}>
                        <Each
                          of={model.value.plot?.profiles ?? []}
                          by={(profile) => profile.key}
                          renew
                        >
                          {(profile) => (
                            <g
                              style={{ '--pm-chart-mark': profile.paint }}
                              data-active={
                                view.value.active && walked.value === profile.series
                                  ? ''
                                  : undefined
                              }
                            >
                              <path class={styles.wash} d={profile.d} />
                              <path class={styles.stroke} d={profile.d} />
                              <Each of={profile.vertices} by={(vertex) => vertex.key} renew>
                                {(vertex) => (
                                  <circle
                                    class={styles.vertex}
                                    cx={vertex.x}
                                    cy={vertex.y}
                                    r={vertex.r}
                                    data-active={
                                      view.value.index === vertex.index &&
                                      walked.value === profile.series
                                        ? ''
                                        : undefined
                                    }
                                  />
                                )}
                              </Each>
                            </g>
                          )}
                        </Each>
                      </g>
                      {/* labels */}
                      <g class={styles.labels}>
                        <Each of={model.value.plot?.labels ?? []} by={(spoke) => spoke.key} renew>
                          {(spoke) => (
                            <text x={spoke.x} y={spoke.y} text-anchor={spoke.anchor}>
                              {spoke.text}
                            </text>
                          )}
                        </Each>
                      </g>
                    </g>
                  </svg>
                ) : null}
              </div>
            )}
            {readout.value.tooltip !== null ? (
              <div
                class={chartTooltip.tooltip}
                style={{
                  '--pm-chart-tip-x': `${readout.value.tooltip?.x}px`,
                  '--pm-chart-tip-y': `${readout.value.tooltip?.y}px`,
                }}
                data-indicator={readout.value.tooltip?.indicator}
                data-side={readout.value.tooltip?.side}
                aria-hidden="true"
              >
                {readout.value.tooltip?.header !== undefined ? (
                  <p class={chartTooltip.header}>{readout.value.tooltip?.header}</p>
                ) : null}
                <ul class={chartTooltip.rows}>
                  <Each of={readout.value.tooltip?.rows ?? []} by={(row) => row.key} renew>
                    {(row) => (
                      <li class={chartTooltip.row}>
                        <span class={chartTooltip.key} style={{ '--pm-chart-key': row.paint }} />
                        <span class={chartTooltip.value}>{row.value}</span>
                        <span class={chartTooltip.label}>{row.label}</span>
                      </li>
                    )}
                  </Each>
                </ul>
              </div>
            ) : null}
          </div>
          {/* x axis */}
          <div class={chartFrame.xAxis} />
        </div>
        {model.value.legend ? (
          model.value.painted.length > 0 ? (
            <ul class={styles.legend} data-key-shape="line">
              <Each of={model.value.painted} by={(entry) => entry.key} renew>
                {(entry) => (
                  <li class={chartLegend.item}>
                    <button
                      class={chartLegend.key}
                      type="button"
                      aria-pressed={hidden.value.has(entry.key) ? 'false' : 'true'}
                      onclick={() => (hidden.value = toggleSeries(hidden.value, entry.key))}
                    >
                      <span
                        class={chartLegend.swatch}
                        style={{ '--pm-chart-key': entry.paint }}
                        aria-hidden="true"
                      />
                      {entry.icon !== undefined ? (
                        <span class={chartLegend.glyph}>
                          <Icon name={entry.icon} size="sm" />
                        </span>
                      ) : null}
                      <span class={chartLegend.label}>{entry.label}</span>
                    </button>
                  </li>
                )}
              </Each>
            </ul>
          ) : null
        ) : null}
        {/* summary */}
        <span class={a11y.visuallyHidden}>{model.value.summary}</span>
        {/* twin */}
        <div class={chartTwin.twin} data-state={twinOpen.value ? 'open' : 'closed'}>
          <div class={chartTwin.toggle}>
            <Button
              variant="ghost"
              tone="neutral"
              size="sm"
              icon="table"
              iconOnly={true}
              label={
                twinOpen.value
                  ? props.messages.hideTable(props.label)
                  : props.messages.showTable(props.label)
              }
              onClick={() => (twinOpen.value = !twinOpen.value)}
            />
          </div>
          {twinOpen.value ? (
            <div class={chartTwin.table}>
              <Table
                label={props.messages.tableLabel(props.label)}
                caption={props.messages.tableLabel(props.label)}
              >
                <TableHead>
                  <TableRow>
                    <Each of={model.value.twin.columns} by={(column) => column.key} renew>
                      {(column) => (
                        <TableHeader numeric={column.numeric}>{column.label}</TableHeader>
                      )}
                    </Each>
                  </TableRow>
                </TableHead>
                <TableBody>
                  <Each of={model.value.twin.rows} by={(_row, line) => line} renew>
                    {(row) => (
                      <TableRow>
                        <Each
                          of={row}
                          by={(_cell, cellIndex) =>
                            model.value.twin.columns[cellIndex]?.key ?? cellIndex
                          }
                          renew
                        >
                          {(cell, cellIndex) => (
                            <TableCell numeric={model.value.twin.columns[cellIndex()]?.numeric}>
                              {cell === '' ? '—' : cell}
                            </TableCell>
                          )}
                        </Each>
                      </TableRow>
                    )}
                  </Each>
                </TableBody>
              </Table>
            </div>
          ) : null}
        </div>
        {/* live region */}
        <span class={a11y.visuallyHidden}>
          <div aria-live="polite" aria-atomic="true">
            {readout.value.announcement}
          </div>
        </span>
      </figure>
    )
  })
}
